func applyAll(vatPath string) error {
	matches, err := listSQL(migDir)
	if err != nil {
		return err
	}
	st, err := vat.Parse(vatPath)
	if err != nil {
		st = &vat.Store{Table: "tries", Cols: []string{}, Rows: nil}
	}
